-- Sistema de Raites Universitarios - UNITI
-- Diana Sabas y Miguel Martínez - Corregido
DROP TABLE IF EXISTS viaje;
DROP TABLE IF EXISTS vehiculo;
DROP TABLE IF EXISTS usuario;
CREATE TABLE usuario (id_usuario TEXT PRIMARY KEY NOT NULL, nombre TEXT, direccion TEXT);
CREATE TABLE vehiculo (id_vehiculo TEXT PRIMARY KEY NOT NULL, tipo_vehiculo TEXT, numero_pasajeros INTEGER, id_usuario TEXT, FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario));
CREATE TABLE viaje (id_viaje TEXT PRIMARY KEY NOT NULL, origen TEXT, destino TEXT, horario TEXT, id_usuario TEXT, id_vehiculo TEXT, FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario), FOREIGN KEY (id_vehiculo) REFERENCES vehiculo(id_vehiculo));
